        see=["precipitation-types", "bomb-cyclone", "cold-waves", "rain-shadow", "extremes"],
        scene={"view": {"lon": -80, "lat": 43, "dist": 2.4}, "color": "t850", "month": 12, "shade": False, "names": ["places"]},
